Here is the commit message:
i3c: master: renesas: Fix memory leak in
 renesas_i3c_i3c_xfers()

The xfer structure allocated by renesas_i3c_alloc_xfer() was never freed
in the renesas_i3c_i3c_xfers() function. Use the __free(kfree) cleanup
attribute to automatically free the memory when the variable goes out of
scope.

Fixes: d028219a9f14 ("i3c: master: Add basic driver for the Renesas I3C controller")
Tested-by: Tommaso Merciai <tommaso.merciai.xr@bp.renesas.com>
Reviewed-by: Tommaso Merciai <tommaso.merciai.xr@bp.renesas.com>
Reviewed-by: Frank Li <Frank.Li@nxp.com>
Signed-off-by: Felix Gu <ustc.gu@gmail.com>
Link: https://patch.msgid.link/20260406-renesas-v3-1-4b724d7708f4@gmail.com
Signed-off-by: Alexandre Belloni <alexandre.belloni@bootlin.com>

Here is the root cause:
The function renesas_i3c_i3c_xfers() allocates a transfer structure via renesas_i3c_alloc_xfer() but never frees it, causing a memory leak.

Here is the patch:
 #include <linux/bitfield.h>
 #include <linux/bitops.h>
+#include <linux/cleanup.h>
 #include <linux/clk.h>
 #include <linux/completion.h>

 static int renesas_i3c_i3c_xfers(struct i3c_dev_desc *dev, struct i3c_xfer *i3c_xfers,
 				 int i3c_nxfers, enum i3c_xfer_mode mode)
 {
 	struct i3c_master_controller *m = i3c_dev_get_master(dev);
 	struct renesas_i3c *i3c = to_renesas_i3c(m);
 	struct renesas_i3c_i2c_dev_data *data = i3c_dev_get_master_data(dev);
-	struct renesas_i3c_xfer *xfer;
 	int i;

 	/* Enable I3C bus. */
 	renesas_i3c_bus_enable(m, true);

-	xfer = renesas_i3c_alloc_xfer(i3c, 1);
+	struct renesas_i3c_xfer *xfer __free(kfree) = renesas_i3c_alloc_xfer(i3c, 1);
 	if (!xfer)
 		return -ENOMEM;

 	init_completion(&xfer->comp);

 	for (i = 0; i < i3c_nxfers; i++) {
 		struct renesas_i3c_cmd *cmd = xfer->cmds;

 		/* Calculate the Transfer Command Descriptor */
 		cmd->rnw = i3c_xfers[i].rnw;
 		cmd->cmd0 = NCMDQP_DEV_INDEX(data->index) | NCMDQP_MODE(0) |
 			    NCMDQP_RNW(cmd->rnw) | NCMDQP_ROC | NCMDQP_TOC;

 		if (i3c_xfers[i].rnw) {
 			cmd->rx_count = 0;
 			cmd->cmd0 |= NCMDQP_TID(I3C_READ);
 			cmd->rx_buf = i3c_xfers[i].data.in;
 			cmd->len = i3c_xfers[i].len;
 			i3c->internal_state = I3C_INTERNAL_STATE_CONTROLLER_READ;
 		} else {
 			cmd->tx_count = 0;
 			cmd->cmd0 |= NCMDQP_TID(I3C_WRITE);
 			cmd->tx_buf = i3c_xfers[i].data.out;
 			cmd->len = i3c_xfers[i].len;
 			i3c->internal_state = I3C_INTERNAL_STATE_CONTROLLER_WRITE;
 		}

 		if (!i3c_xfers[i].rnw && i3c_xfers[i].len > 4) {
 			i3c_writel_fifo(i3c->regs + NTDTBP0, cmd->tx_buf, cmd->len);
 			if (cmd->len > NTDTBP0_DEPTH * sizeof(u32))
 				renesas_set_bit(i3c->regs, NTIE, NTIE_TDBEIE0);
 		}

 		renesas_i3c_wait_xfer(i3c, xfer);
 	}

 	return 0;
 }



